// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(uint256 amt, address to) public {
        vm.assume(amt <= VALUE_CAP);
        // admissible domain: positive, sane deposit; recipient neither the creator (test contract)
        // nor the contract itself, and not a precompile-adjacent address
        vm.assume(amt > 0 && amt <= 1000 ether);
        vm.assume(to != address(this) && to != address(c) && uint160(to) > 100);

        // fund and deposit into c; the test contract is the creator (deployed in setUp)
        vm.deal(address(this), amt);
        c.deposit{value: amt}();

        uint256 recipientBefore = to.balance;
        uint256 contractBefore = address(c).balance;

        c.migrateTo(to);

        // universal rule: the requested recipient receives the contract's entire balance,
        // and the contract is emptied
        assertTrue(to.balance == recipientBefore + contractBefore && address(c).balance == 0);
    }
}
